@Component({
    selector: "app-tent-row",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ TentComponent, IconButtonComponent ],
    template: `<div class="row"><app-tent [name]="name()" /><app-icon-button icon="pencil" label="Rename tent" (press)="edit()" /><app-icon-button icon="trash" (press)="remove()" /></div>`
})
export class TentRowComponent {
    readonly name = input("");
    edit(): void {}
    remove(): void {}
}
    imports: [ RationComponent, IconButtonComponent ],
    template: `
        <ul>
            @for (row of rows; track row) {
                <li><app-ration [grain]="row" /></li>
            }
        </ul>
        <app-icon-button icon="download" (press)="exportData()" />
    `
})
export class SupplyTableComponent {
    imports: [ TentRowComponent, IconButtonComponent ],
    template: `
        @for (tent of tents; track tent) {
            <app-tent-row [name]="tent" />
        }
        <app-icon-button
            icon="plus"
            (press)="add()"
        />
    `
})
export class TentListComponent {
    readonly tents = [ "Praetorium", "Quaestorium", "Valetudinarium" ];
    imports: [ IconButtonComponent, IconButtonGroupComponent ],
    template: `
        <app-icon-button-group>
            <app-icon-button icon="search" label="Search" (press)="find()" />
            <app-icon-button icon="refresh" (press)="reload()" />
            <app-icon-button
                icon="close"
                (press)="dismiss()"
            />

